export function buildGeometry(THREE, spec, scale = 1) {
  const geo = new THREE.BufferGeometry();
  const pos = new Float32Array(spec.pos);
  if (scale !== 1) {
    for (let i = 0; i < pos.length; i++) pos[i] *= scale;
  }
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  geo.setAttribute('normal', new THREE.BufferAttribute(new Float32Array(spec.norm), 3));
  geo.setIndex(spec.idx);
  geo.computeBoundingSphere();
  return geo;
}

export function makeKeycapGeometry(THREE, scale = 1) {
  return buildGeometry(THREE, KEYCAP_SPEC, scale);
}

export function makeAppleBodyGeometry(THREE, scale = 1) {
  return buildGeometry(THREE, APPLE_BODY_SPEC, scale);
}

export function makeAppleLeafGeometry(THREE, scale = 1) {
  return buildGeometry(THREE, APPLE_LEAF_SPEC, scale);
}

export function makeCrownGeometry(THREE, scale = 1) {
  return buildGeometry(THREE, CROWN_SPEC, scale);
}
